/**
 * GitLab REST API v4, through the connection's Named Credential (default RLY_GitLab,
 * URL https://gitlab.com/api/v4 or your self-managed GitLab's /api/v4).
 * Token: project access token with the api scope (needed to start a pipeline), role Developer.
 * Repository is the project path, for example your-group/salesforce.
 * The pipeline is started on the workflow branch with the release values as CI/CD variables.
 */
public with sharing class RlyGitLabService extends RlyGitProvider {

    private static final Pattern REPO_PATTERN = Pattern.compile('^[A-Za-z0-9_.-]+(/[A-Za-z0-9_.-]+)+$');

    private String project; // URL-encoded path

    protected override void init(RlySettings.Connection c) {
        super.init(c);
        this.project = EncodingUtil.urlEncode(c.repository.trim(), 'UTF-8');
    }

    public override Pattern repositoryPattern() { return REPO_PATTERN; }
    public override String repositoryHint() { return 'group/project (the project path)'; }
    public override String changeLabel() { return 'merge request'; }

    private String p(String path) {
        return '/projects/' + project + path;
    }

    public override Boolean branchExists(String branch) {
        HttpResponse res = send('GET', p('/repository/branches/' + RlyGitProvider.enc(branch)), null, null);
        if (res.getStatusCode() == 404) {
            return false;
        }
        assertOk(res, 'Branch lookup');
        return true;
    }

    public override List<String> listBranches() {
        List<String> names = new List<String>();
        for (Integer page = 1; page <= 3; page++) {
            HttpResponse res = send('GET', p('/repository/branches?per_page=100&page=' + page), null, null);
            assertOk(res, 'Branch list');
            List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
            for (Object o : rows) {
                names.add(String.valueOf(((Map<String, Object>) o).get('name')));
            }
            if (rows.size() < 100) {
                break;
            }
        }
        return names;
    }

    public override String getFileRaw(String filePath, String ref) {
        HttpResponse res = send('GET', p('/repository/files/' + RlyGitProvider.enc(filePath) + '/raw?ref=' + RlyGitProvider.enc(ref)), null, null);
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'File read');
        return res.getBody();
    }

    public override List<Entry> listDir(String folderPath, String ref) {
        List<Entry> out = new List<Entry>();
        for (Integer page = 1; page <= 20; page++) {
            HttpResponse res = send('GET', p('/repository/tree?path=' + RlyGitProvider.enc(folderPath) + '&ref=' + RlyGitProvider.enc(ref)
                + '&per_page=100&page=' + page), null, null);
            if (res.getStatusCode() == 404) {
                return out;
            }
            assertOk(res, 'Folder read');
            List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
            for (Object o : rows) {
                Map<String, Object> m = (Map<String, Object>) o;
                out.add(RlyGitProvider.entry(String.valueOf(m.get('name')), m.get('type') == 'tree'));
            }
            if (rows.size() < 100) {
                break;
            }
        }
        return out;
    }

    public override Comparison compare(String baseRef, String head) {
        HttpResponse res = send('GET', p('/repository/compare?from=' + RlyGitProvider.enc(baseRef) + '&to=' + RlyGitProvider.enc(head) + '&straight=false'), null, null);
        if (res.getStatusCode() == 404) {
            throw new GitException('Branch ' + head + ' or ' + baseRef + ' was not found.');
        }
        assertOk(res, 'Compare');
        Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
        Comparison c = new Comparison();
        List<Object> commits = (List<Object>) body.get('commits');
        c.aheadBy = commits == null ? 0 : commits.size();
        c.behindBy = 0;
        c.url = body.get('web_url') == null ? null : String.valueOf(body.get('web_url'));
        List<Object> diffs = (List<Object>) body.get('diffs');
        if (diffs != null) {
            for (Object o : diffs) {
                Map<String, Object> d = (Map<String, Object>) o;
                c.files.add(status(d) + '  ' + String.valueOf(d.get('new_path')));
            }
        }
        return c;
    }

    public override Started startPipeline(Map<String, String> inputs) {
        List<Map<String, String>> variables = new List<Map<String, String>>();
        for (String k : inputs.keySet()) {
            variables.add(new Map<String, String>{ 'key' => k.toUpperCase(), 'value' => inputs.get(k) });
        }
        HttpResponse res = send('POST', p('/pipeline'), JSON.serialize(new Map<String, Object>{
            'ref' => conn.workflowRef, 'variables' => variables }), null);
        assertOk(res, 'Pipeline start');
        Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
        Started s = new Started();
        s.runId = String.valueOf(body.get('id'));
        s.url = body.get('web_url') == null ? null : String.valueOf(body.get('web_url'));
        return s;
    }

    public override Run findRun(String releaseName, String runMode, String knownRunId) {
        if (String.isBlank(knownRunId)) {
            return null;
        }
        HttpResponse res = send('GET', p('/pipelines/' + RlyGitProvider.enc(knownRunId)), null, null);
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'Pipeline lookup');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(res);
        String status = String.valueOf(m.get('status'));
        Run run = new Run();
        run.id = knownRunId;
        run.url = String.valueOf(m.get('web_url'));
        run.createdAt = RlyGitProvider.parseTime(m.get('created_at'));
        Boolean done = new Set<String>{ 'success', 'failed', 'canceled', 'skipped' }.contains(status);
        run.status = done ? 'completed' : (status == 'running' ? 'in_progress' : 'queued');
        run.conclusion = !done ? null : status == 'success' ? 'success' : status == 'canceled' ? 'cancelled' : 'failure';
        return run;
    }

    public override PullRequest findPullRequest(String branch, String target) {
        HttpResponse res = send('GET', p('/merge_requests?state=all&order_by=created_at&sort=desc&per_page=1&source_branch='
            + RlyGitProvider.enc(branch) + '&target_branch=' + RlyGitProvider.enc(target)), null, null);
        assertOk(res, 'Merge request lookup');
        List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
        if (rows.isEmpty()) {
            return null;
        }
        Map<String, Object> m = (Map<String, Object>) rows[0];
        PullRequest pr = new PullRequest();
        pr.num = RlyGitProvider.toInt(m.get('iid'));
        pr.url = String.valueOf(m.get('web_url'));
        String state = String.valueOf(m.get('state'));
        pr.merged = state == 'merged';
        pr.state = state == 'opened' || state == 'locked' ? 'open' : 'closed';
        return pr;
    }

    public override List<PrFile> pullFiles(Integer prNumber, String target, String branch) {
        List<PrFile> out = new List<PrFile>();
        Integer budget = 2000000;
        for (Integer page = 1; page <= 3; page++) {
            HttpResponse res = send('GET', p('/merge_requests/' + prNumber + '/diffs?per_page=100&page=' + page), null, null);
            assertOk(res, 'Merge request files');
            List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
            for (Object o : rows) {
                Map<String, Object> d = (Map<String, Object>) o;
                PrFile f = new PrFile();
                f.filename = String.valueOf(d.get('new_path'));
                f.status = status(d);
                budget = RlyGitProvider.fitPatch(f, d.get('diff') == null ? '' : String.valueOf(d.get('diff')), budget);
                RlyGitProvider.countLines(f);
                out.add(f);
            }
            if (rows.size() < 100) {
                break;
            }
        }
        return out;
    }

    private static String status(Map<String, Object> d) {
        return d.get('new_file') == true ? 'added' : d.get('deleted_file') == true ? 'removed'
            : d.get('renamed_file') == true ? 'renamed' : 'modified';
    }
}
